import { useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'

import ImageIcon from '@mui/icons-material/Image'
import LocalOfferIcon from '@mui/icons-material/LocalOffer'
import StorefrontIcon from '@mui/icons-material/Storefront'
import { Box, Button, Card, Chip, Container, Divider, Stack, Typography, useMediaQuery, useTheme } from '@mui/material'
import type { GridColDef, GridRenderCellParams } from '@mui/x-data-grid'
import { DataGrid } from '@mui/x-data-grid'

import { DEFAULT_DELETE_MESSAGE } from 'src/data/cofirmDialogueMessages'

import { formatPartnerBenefitDate } from 'src/utils/partnerBenefits'

import ConfirmDialog from 'src/components/ConfirmDialog'
import PageTitleWrapper from 'src/components/PageTitleWrapper'

import { usePartnerBenefits } from 'src/hooks/usePartnerBenefits'

interface StoreTableRow {
  id: number
  name: string
  mapLink: string
  imageUrl?: string | null
  couponCount: number
  createdAt: string
}

const BenefitStoreManagePage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const navigate = useNavigate()
  const { stores, coupons, deletePartnerStore } = usePartnerBenefits({ mode: 'admin' })
  const [deleteTargetStoreId, setDeleteTargetStoreId] = useState<number | null>(null)

  const activeStores = stores.filter(store => !store.deletedAt)
  const activeCoupons = coupons.filter(coupon => !coupon.deletedAt)
  const storeRows: StoreTableRow[] = activeStores.map(store => ({
    id: store.id,
    name: store.name,
    mapLink: store.mapLink,
    imageUrl: store.imageUrl,
    couponCount: activeCoupons.filter(coupon => coupon.partnerStoreId === store.id).length,
    createdAt: store.createdAt ? formatPartnerBenefitDate(store.createdAt) : '-'
  }))

  const handleCouponManageButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-coupons')
  }

  const handleAdminButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin')
  }

  const handleStoreRegisterButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-store-form')
  }

  const handleEditStoreButtonClick =
    (storeId: number): React.MouseEventHandler<HTMLButtonElement> =>
    () => {
      navigate(`/admin/benefit-store-form?benefitStoreId=${storeId}`)
    }

  const handleDeleteStoreButtonClick =
    (storeId: number): React.MouseEventHandler<HTMLButtonElement> =>
    () => {
      setDeleteTargetStoreId(storeId)
    }

  const handleDeleteDialogClose: React.MouseEventHandler<HTMLButtonElement> = () => {
    setDeleteTargetStoreId(null)
  }

  const handleDeleteDialogSubmit: React.MouseEventHandler<HTMLButtonElement> = async () => {
    if (!deleteTargetStoreId) return

    try {
      await deletePartnerStore(deleteTargetStoreId)
    } catch {
      return
    } finally {
      setDeleteTargetStoreId(null)
    }
  }

  const columns: GridColDef<StoreTableRow>[] = [
    { field: 'name', headerName: '가게명', flex: 1, minWidth: 180 },
    {
      field: 'imageUrl',
      headerName: '이미지',
      flex: 0.7,
      minWidth: 120,
      renderCell: (params: GridRenderCellParams<StoreTableRow>) =>
        params.value ? (
          <Stack direction="row" spacing={1} alignItems="center">
            <ImageIcon color="success" fontSize="small" />
            <Typography variant="body2">등록됨</Typography>
          </Stack>
        ) : (
          <Typography variant="body2" color="text.secondary">
            없음
          </Typography>
        )
    },
    { field: 'mapLink', headerName: '지도 링크', flex: 1.3, minWidth: 220 },
    {
      field: 'couponCount',
      headerName: '연결 쿠폰',
      flex: 0.7,
      minWidth: 110,
      align: 'center',
      headerAlign: 'center',
      renderCell: (params: GridRenderCellParams<StoreTableRow>) => (
        <Chip label={`${params.value}개`} size="small" color="success" variant="outlined" />
      )
    },
    { field: 'createdAt', headerName: '등록일', flex: 0.7, minWidth: 120 },
    {
      field: 'actions',
      headerName: '관리',
      flex: 0.9,
      minWidth: 170,
      sortable: false,
      filterable: false,
      renderCell: (params: GridRenderCellParams<StoreTableRow>) => (
        <Stack direction="row" spacing={1}>
          <Button variant="outlined" size="small" onClick={handleEditStoreButtonClick(params.row.id)}>
            수정
          </Button>
          <Button variant="outlined" color="error" size="small" onClick={handleDeleteStoreButtonClick(params.row.id)}>
            삭제
          </Button>
        </Stack>
      )
    }
  ]

  return (
    <>
      <Helmet>
        <title>등록된 제휴 가게 - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={2}>
          <Box>
            <Typography variant={isMobile ? 'h4' : 'h3'}>등록된 제휴 가게</Typography>
            <Typography color="text.secondary" sx={{ mt: 1 }}>
              등록된 제휴 가게의 이름, 지도 링크, 연결된 쿠폰 수를 확인하고 수정하거나 삭제할 수 있습니다.
            </Typography>
          </Box>
          <Stack direction="row" spacing={1}>
            <Button variant="contained" onClick={handleStoreRegisterButtonClick}>
              가게 등록
            </Button>
            <Button variant="outlined" onClick={handleCouponManageButtonClick}>
              쿠폰 관리 보기
            </Button>
            <Button variant="outlined" onClick={handleAdminButtonClick}>
              어드민 페이지
            </Button>
          </Stack>
        </Stack>
      </PageTitleWrapper>
      <Container maxWidth="xl">
        <Card sx={{ boxShadow: theme.header.boxShadow }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ p: 2.5 }}>
            <Chip icon={<StorefrontIcon />} label={`등록된 가게 ${activeStores.length}곳`} color="primary" />
            <Chip icon={<LocalOfferIcon />} label={`연결된 쿠폰 ${activeCoupons.length}개`} color="success" />
          </Stack>
          <Divider />
          <Box sx={{ width: '100%' }}>
            <DataGrid
              autoHeight
              rows={storeRows}
              columns={columns}
              pageSizeOptions={[5, 10, 25]}
              initialState={{ pagination: { paginationModel: { pageSize: 10 } } }}
              disableRowSelectionOnClick
            />
          </Box>
        </Card>
      </Container>
      <ConfirmDialog
        open={deleteTargetStoreId !== null}
        handleClose={handleDeleteDialogClose}
        handleSubmit={handleDeleteDialogSubmit}
        confirmMessage={DEFAULT_DELETE_MESSAGE}
      />
    </>
  )
}

export default BenefitStoreManagePage
